const qs=["Daniso Horsa Ethiopia Natural","Marlon Bolaños Washed Ají Bourbon","Cloister Reserve Blend"];
const out=[];
for(const q of qs){
await page.goto("https://www.coffeereview.com/?s="+encodeURIComponent(q));
const links=await page.locator("h2 a, h3 a").evaluateAll(a=>a.map(x=>[x.innerText,x.href]));
out.push(links.filter(l=>/daniso|marlon|cloister/i.test(l[0])));
}
return out

